const AFTERMATH_TITLES=["钥匙与门槛", "信暂时收进口袋", "在纸的空白处", "带上门，走到街上", "把信收好", "墓地之外的城市", "另一位来客", "杯中的一点酒", "论点留在听者之间", "同一刻，另一条街", "声音回来时", "先离开这里", "目光已经换了方向", "门里仍有人在工作", "走回现实的夜色", "暂歇之后", "到门槛为止", "她自己的声音"];const app=document.querySelector('#app');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function read(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}function save(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('无法保存，请检查浏览器存储权限');return false}}function toast(s){const e=document.querySelector('#toast');e.textContent=s;e.style.display='block';setTimeout(()=>e.style.display='none',2500)}const validN=x=>Number.isInteger(x)&&x>=1&&x<=18;let n=Number(new URLSearchParams(location.search).get('chapter'));if(!validN(n))n=1;let at=0,choice='',marks=[],journal=[];const key='ulysses-v2-game';const portraits={'布卢姆':'bloom','斯蒂芬':'stephen','摩莉':'molly'};function nodes(){const s=STORY[n];const a=[{type:'intro',role:s.role},{type:'dialogue',role:s.role},{type:s.kind,role:s.role},{type:'reply',role:s.role},{type:'aftermath',role:s.role}];if(n===7)a.push({type:'switch',role:'斯蒂芬',title:'同一座报馆，另一件事',text:'广告请求留在布卢姆的业务线上。你现在是斯蒂芬，处理迪希托付的信；这是原作报馆章节中的另一段，不是两人会合。',items:['校长的信','收信与刊载的区别','自己的去向']});if([14,15,16,17].includes(n))a.push({type:'switch',role:'斯蒂芬',title:n===17?'由门内，到门外':'另一位当事人的位置',text:n===17?'体验斯蒂芬离开的节点。两人的靠近并没有抹掉分歧；此处的选择是留意什么，不改写是否留下。':'此处转向斯蒂芬参与的原作情境。布卢姆的私人记忆不会自动进入他的意识，作品外的阅读记录也不会成为现场对白。',items:['已经说出口的话','眼前可见的行动','仍未说出的感受']});if(n===13)a.push({type:'switch',role:'布卢姆',title:'此处，叙述转向布卢姆',text:'到达后段才恢复布卢姆的体验。格蒂相关段落保留其独立语言；它们没有全部变成布卢姆的知识。',items:['前段的叙述归属','布卢姆的判断','两者之间的距离']});a.push({type:'end',role:n===18?'摩莉':s.role});return a}function current(){return nodes()[at]}function remember(){save(key,{version:2,n,at,choice,marks,journal})}function source(term){const qi=STORY[n].items.indexOf(term),exact=typeof QUOTE_INDEX!=='undefined'&&qi>=0?QUOTE_INDEX[n]?.[qi]:null;if(exact)return '〔所给译本正文页内节选 · PDF第'+exact.page+'页 · 关联词：'+exact.keyword+'；编辑关联不单独作为身份定义〕\n'+exact.text;const c=CHAPTERS[n-1],text=c.body,anchors=['穆利根','迪希','海','猫','肥皂','马车','南尼蒂','三明治','莎士比亚','康米','杜丝','市民','格蒂','护士','贝拉','咖啡','钥匙','我愿意'];const terms=[['碗','早饭','钥匙'],['薪','信','学生'],['脚','海','风'],['猫','茶','托盘'],['信','肥皂','药'],['车','马','说'],['剪报','钥匙','合同'],['三明治','酒','人'],['莎士比亚','说','想'],['康米','博伊兰','总督'],['车','歌','琴'],['市民','我','天使'],['格蒂','布卢姆','她'],['护士','说','天主'],['贝拉','布卢姆','鲁迪'],['咖啡','水手','也许'],['钥匙','可可','斯蒂芬'],['我','想','愿意']];const item=STORY[n].items.indexOf(term);let actual=term,i=text.indexOf(actual),related=false;if(i<0&&item>=0){actual=terms[n-1][item];i=text.indexOf(actual);related=true}if(i<0){actual=anchors[n-1];i=text.indexOf(actual);related=true}if(i<0)return '此项为编辑关联。请打开对应章节或原PDF核对，当前提取正文中未找到精确匹配。';let start=text.lastIndexOf('\n',i);start=start<0?0:start;let end=text.indexOf('\n',i+actual.length);if(end<0)end=text.length;let part=text.slice(start,end).trim();if(part.length>1400)part=part.slice(0,1400)+'〔本段尚未结束〕';return (related?'当前条目为编辑关联；以下为本章相关文字，不是该条目的逐字定义。\n':'')+'〔译文片段；匹配词：'+actual+'；PDF第'+c.start+'页起，页内位置请用原PDF核对〕\n'+part}function advance(){at++;marks=[];remember();draw()}function spritePath(id){let mood=null;if(id==='bloom'&&n===12)mood='bloom-tense';else if(id==='bloom'&&n>=16)mood='bloom-weary';else if(id==='stephen')mood=n===9?'stephen-arguing':'stephen-guarded';else if(id==='molly'&&n===18)mood=choice.includes('记忆')?'molly-reflective':'molly-resolute';return mood?'assets/archive/'+mood+'.webp':'assets/actor-'+id+'.webp'}function draw(){const s=STORY[n],c=CHAPTERS[n-1],node=current(),role=node.role;let speaker='',portrait='',text='',controls='',kind='游戏原创演绎／事件概述';if(node.type==='intro'){text=`<span class="stamp">场景背景</span><h2>${esc(s.title)}</h2><p>${esc(s.context)}</p><div class="task"><b>当前任务</b><p>${esc(c.为何来_企划任务)}</p><small>完成后：${esc(s.outro)}</small></div>`;controls='<button class="primary" id="next">进入场景 →</button>'}else if(node.type==='dialogue'){speaker=s.speaker;portrait=[10,13].includes(n)?null:s.portrait;kind=[10,13].includes(n)?'非操控叙述 · 编辑说明':s.portrait?'游戏改编对白 · 非乔伊斯原句':'内心／叙述体验 · 游戏改写';text=`<span class="speaker">${esc(speaker)}</span><h2>${esc(s.title)}</h2><p class="spoken">${esc(s.line)}</p><p class="stage-direction">${esc(s.context)}</p>`;controls='<button class="primary" id="next">继续 →</button>'}else if(node.type==='reply'){speaker=role;portrait=portraits[role];kind='玩家注意路径 · 不改写既定事件';text=`<span class="speaker">${esc(role)}</span><h2>${esc(choice)}</h2><div class="feedback">${esc(s.feedback)}</div><p>本次记录：${esc(choice)}。另一条路径可以回看，原作行动仍按先后继续。</p>`;controls='<button id="replay">换一种注意方式</button><button class="primary" id="next">接续原作行动 →</button>'}else if(node.type==='aftermath'){text=`<span class="eyebrow">行动之后 / 层次与来源</span><h2>${esc(AFTERMATH_TITLES[n-1])}</h2><p>${esc(s.aftermath)}</p>${n===18?'<blockquote>〔所给译文短摘引 · PDF1156页〕<br>于是我说 嗯 我愿意 嗯。</blockquote>':''}<details class="notice"><summary>本幕的原著与改编边界</summary>${esc(c.不可改写边界)}</details>`;controls='<button class="primary" id="next">继续这一幕 →</button>'}else if(node.type==='switch'){kind='固定改编换角节点';text=`<span class="stamp">换角 · ${esc(role)}</span><h2>${esc(node.title)}</h2><p>${esc(node.text)}</p><div class="inspect">${node.items.map((v,i)=>`<button data-item="${i}">${esc(v)}</button>`).join('')}</div><div id="detail" class="note-sheet" role="status">选择一项，记录此时角色能够知道什么。</div>`;controls='<button id="next" class="primary" disabled>记录一项后继续 →</button>'}else if(node.type==='end'){kind='精选节点已完成';text=`<span class="stamp">本幕精选体验完成</span><h2>${n===18?'回到都柏林的一天':esc((n+1)+'. '+CHAPTERS[n].界面副题_企划拟定)}</h2><p>${esc(s.outro)}</p><div class="notice">体验完成不代表整章原文已读。游戏改编、原著事件概述及译文检索片段已分别标识。</div>`;controls=`${n<18?'<button id="continue" class="primary">进入下一幕 →</button>':'<a class="button primary" href="index.html#map">回到地图 →</a>'}<a class="button" href="index.html#chapter/${n}">阅读对应章节 ↗</a>`}else{kind=({objects:'物件关联',sound:'声音与文字声源',question:'问答与归属',layers:'叙述分层',montage:'并行镜头',memory:'记忆与节奏'})[node.type]||'观察';text=`<span class="eyebrow">${esc(kind)}</span><h2>${esc(({objects:'先触到眼前的东西。',sound:'声音各有来处。',question:'问题并非抢答。',layers:'把行动与讲述分开。',montage:'镜头切换，时间并不顺行。',memory:'让记忆保有回流。'})[node.type])}</h2><p>${esc(c.现在做什么_玩家动作)}</p><div class="inspect ${esc(node.type)}">${s.items.map((v,i)=>`<button data-item="${i}">${String(i+1).padStart(2,'0')}　${esc(v)}</button>`).join('')}</div><div id="detail" class="note-sheet" role="status">${node.type==='memory'?'记忆标记属于玩家，不会改写摩莉的意识。':'点选两个条目。通过文字也能完成，不依赖拖拽、声音或速度。'}</div><a id="quote-source" class="scribble" hidden target="_blank" rel="noopener">核对本段原PDF ↗</a><div class="choices" id="choicebox" ${node.type==='memory'?'':'hidden'}>${s.choices.map((v,i)=>`<button data-choice="${i}">${esc(v)}</button>`).join('')}</div>`}const img=portrait?`<img class="actor-sprite" src="${spritePath(portrait)}" alt="${esc(speaker)}：AI艺术演绎立绘">`:'';app.innerHTML=`<section class="scene"><div class="scene-title"><div><span class="eyebrow">BEFORE THE WAY HOME / 归家之前</span><h1>${String(n).padStart(2,'0')} · ${esc(c.界面副题_企划拟定)}</h1></div><a class="back" href="index.html#map">关卡地图 ↗</a></div><div class="role">${['城市群像','格蒂相关叙述'].includes(role)?'非操控叙述':'当前扮演：'+esc(role)} <span>／ ${esc(kind)}</span></div><div class="progress" aria-label="节点${at+1}/${nodes().length}">${nodes().map((_,i)=>`<i class="${at>=i?'active':''}"></i>`).join('')}</div><div class="theatre" style="--scene:url('assets/scene-${String(n).padStart(2,'0')}.webp')"><div class="scene-painting" role="img" aria-label="${esc(c.界面副题_企划拟定)}场景艺术演绎"></div>${img}<div class="scene-copy ${portrait?'with-actor':''}">${text}<div class="choices">${controls}</div></div></div><div class="scene-bottom"><a href="index.html#chapter/${n}">查看来源与完整本地正文 ↗</a><a href="assets/scene-${String(n).padStart(2,'0')}.webp" target="_blank" rel="noopener">查看完整场景画幅 ↗</a><button id="notes">本次手札 (${journal.length})</button><span>对白为游戏改编 · 可随时查看对应原文</span></div><div id="journal" hidden class="note-sheet"></div></section>`;const bind=(id,f)=>{const x=document.getElementById(id);if(x)x.onclick=f};bind('next',advance);bind('continue',()=>{n++;at=0;choice='';marks=[];remember();history.replaceState(null,'','?chapter='+n);draw()});bind('replay',()=>{at=2;marks=[];draw()});bind('notes',()=>{const x=document.querySelector('#journal');x.hidden=!x.hidden;x.textContent=journal.length?journal.map(v=>v).join('\n'):'还没有记录；选择物件、声音或记忆后，会在此保存。'});document.querySelectorAll('[data-item]').forEach(b=>{b.onclick=()=>{const i=Number(b.dataset.item),label=(node.items||s.items)[i];if(!marks.includes(i))marks.push(i);b.classList.add('selected');const qlink=document.querySelector('#quote-source'),qhit=typeof QUOTE_INDEX!=='undefined'?QUOTE_INDEX[n]?.[i]:null;if(qlink&&qhit){qlink.href='../../尤利西斯.pdf#page='+qhit.page;qlink.hidden=true}const entry='第'+n+'幕 · '+role+' · '+label;if(!journal.includes(entry))journal.push(entry);document.querySelector('#notes').textContent='本次手札 ('+journal.length+')';document.querySelector('#detail').textContent=node.type==='switch'?label+'：此处只记录该角色当前可知的信息，不接入另一人物的未公开内心。':source(label);if(['layers','montage','question'].includes(node.type)){const explanations={12:['现场层保留争执、离场与追出；注意选择不取消这些行动。','匿名的“我”有自己的立场，不等于布卢姆，也不等于作者的中立判断。','升天式夸饰扩大了文字规模；它不是城市实景，更不是人物的超能力。'],13:['前段的格蒂相关语言保留自己的位置，不归入布卢姆的内心。','到原作后段转向布卢姆时，才恢复他的体验。','后一个人的判断不会自动抹掉前一层叙述，也不构成中立身份结论。'],14:['护理正在发生，不以旁人的说话声取代。','公共谈话与实际照料并置，声音大并不表示承受了相同的身体压力。','仿古与其他散文姿态是叙述形式；不是护士在向人物朗读文学史。'],15:['先辨认当事人的现场位置与行动，保留离场的原作次序。','舞台指示组织观看，不自动成为人物公开说出口的话。','幻景的声音与变形保留幻景归属，不写进人物真实履历。'],10:['这是城市群像中的生活处境，不是主角遍历全城的任务。','镜头切到另一处，同一时段的生活仍在并行。','车队与街头人物交织，不把切镜解释为同一个人的瞬移。'],9:['这是斯蒂芬提出的论点，不是系统担保的莎士比亚传记事实。','回应有发言者；可以质疑，也可以仍未解决。','未出口的感受保留内心归属，不供其他角色知情反驳。'],16:['可见的到店与饮食行动，与传闻分别记录。','水手的讲法保留他的归属，听见不等于已经证实。','不确定之处可以留下，不必强制猜出一个骗子。'],17:['门与钥匙首先是实际发生的小事。','饮食照料把关系拉近，但不取消两人的距离。','问答把共同点与分歧并置，不是现场审讯或抢答。']};const hint=explanations[n]?.[i]||'把叙述的组织方式与人物当下行动分开看。';document.querySelector('#detail').textContent='〔编辑解释〕'+hint+'\n\n'+source(label);if(node.type==='montage')document.querySelector('.scene-painting').style.backgroundPosition=['left center','center','right center'][i]}if(node.type==='switch'){document.querySelector('#next').disabled=false;document.querySelector('#next').textContent='保留记录，继续 →'}else if(marks.length>=(node.type==='memory'?1:Math.min(2,s.items.length))){document.querySelector('#choicebox').hidden=false}remember()}});document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{choice=s.choices[Number(b.dataset.choice)];if(n===18&&Number(b.dataset.choice)===0){const m='第18幕 · 摩莉 · 当前记忆体验节点';if(!journal.includes(m))journal.push(m)}at++;remember();draw()});if(!['intro','dialogue','reply','aftermath','end'].includes(node.type)&&marks.length){document.querySelectorAll('[data-item]').forEach(b=>{if(marks.includes(Number(b.dataset.item)))b.classList.add('selected')});const box=document.querySelector('#choicebox');if(box&&(marks.length>=2||node.type==='memory'))box.hidden=false;if(node.type!=='switch'){const last=marks[marks.length-1];document.querySelector('#detail').textContent=source(s.items[last]);const q=document.querySelector('#quote-source'),hit=typeof QUOTE_INDEX!=='undefined'?QUOTE_INDEX[n]?.[last]:null;if(q&&hit){q.href='../../尤利西斯.pdf#page='+hit.page;q.hidden=true}}const next=document.querySelector('#next');if(node.type==='switch'&&next)next.disabled=false}if(node.type==='end'){const done=read('ulysses-v2-completed',[]);if(!done.includes(n)){done.push(n);save('ulysses-v2-completed',done)}remember()}window.scrollTo(0,0)}document.querySelector('#resume').onclick=()=>{const s=read(key,null);if(s?.version===2&&validN(s.n)&&Number.isInteger(s.at)){n=s.n;if(s.at<0||s.at>=nodes().length){toast('存档节点无效，原记录未覆盖');return}at=s.at;choice=typeof s.choice==='string'?s.choice:'';marks=Array.isArray(s.marks)?s.marks:[];journal=Array.isArray(s.journal)?s.journal:[];draw();toast('已恢复角色、节点与手札')}else{const old=read('ulysses-game',null);if(old&&validN(old.n)){n=old.n;at=0;draw();toast('已保留原记录，从本章开场继续')}else toast('尚无存档')}};document.querySelector('#motion').onclick=e=>{document.body.classList.toggle('reduced');e.target.setAttribute('aria-pressed',document.body.classList.contains('reduced'))};draw();